<script>
import { ref, watch, reactive, computed, onMounted, onUnmounted, nextTick } from 'vue';
import { VIS, VMAP } from './core/visualizers';
import { Audio, ALGOS } from './core/audio';
import { Engine } from './core/engine';
import { clamp } from './core/palette';
import { loadState, saveState } from './core/persistence';
import { revoke, disposeAudio, disposeEffects } from './core/lifecycle';

const GSCHEMA={amp:{label:'Амплитуда',min:.3,max:2.5,step:.05},speed:{label:'Скорость',min:.1,max:3,step:.05},smooth:{label:'Сглаживание FFT',min:0,max:.95,step:.01},trail:{label:'Шлейф',min:0,max:.97,step:.01},zoomW:{label:'Ширина EQ',min:.4,max:1.6,step:.01},zoomH:{label:'Высота EQ',min:.4,max:1.6,step:.01},posX:{label:'Позиция EQ X',min:0,max:100,step:1},posY:{label:'Позиция EQ Y',min:0,max:100,step:1}};
const MUSIC={edm:{bands:[1.75,1.15,.85,1.05,1.4],smooth:.5,amp:1.35,speed:1.35,algo:'bassPunch',trail:.5},ambient:{bands:[.7,.9,1.2,1.1,1],smooth:.88,amp:.9,speed:.55,algo:'cinematic',trail:.82},rock:{bands:[1.35,1.25,1.45,1.15,1.05],smooth:.66,amp:1.15,speed:1.1,algo:'attack',trail:.4},hiphop:{bands:[1.9,1.3,.9,.85,1.1],smooth:.58,amp:1.25,speed:.95,algo:'beatPulse',trail:.55},classical:{bands:[.8,1,1.2,1.3,1.35],smooth:.82,amp:1,speed:.7,algo:'balanced',trail:.7},podcast:{bands:[.5,1.35,1.8,1.05,.6],smooth:.9,amp:.8,speed:.45,algo:'midFocus',trail:.35}};
const PALETTES=[{name:'Ember',c1:'#ff5a2d',c2:'#ffd166'},{name:'Ice',c1:'#3ea8ff',c2:'#b6f7ff'},{name:'Toxic',c1:'#c6ff3d',c2:'#00d9a3'},{name:'Orchid',c1:'#ff3d9a',c2:'#7b5cff'},{name:'Mono',c1:'#f3f0ea',c2:'#8e8b86'},{name:'Dusk',c1:'#ff8a3d',c2:'#2b4bff'}];
const DEFAULTS={preset:'bars',algo:'balanced',music:'custom',colorMode:'duo',c1:'#ff5a2d',c2:'#3ea8ff',cycle:0,canvasBg:'ink',format:'16:9',amp:1,speed:1,smooth:.58,trail:.35,zoomW:1,zoomH:1,posX:50,posY:50,gBass:1,gLowMid:1,gMid:1,gHighMid:1,gTreble:1,agc:true,demo:true,autoQuality:true};

export default{setup(){
  const audioEl=ref(null),canvasEl=ref(null),frameEl=ref(null),beatEl=ref(null),meterEls=reactive([]);
  const restored=loadState(DEFAULTS,VIS);
  const g=reactive(restored.g),params=reactive(restored.params);
  const dark=ref(restored.dark??document.documentElement.classList.contains('dark'));
  document.documentElement.classList.toggle('dark',dark.value);
  const playing=ref(false),mic=ref(false),hasFile=ref(false),drag=ref(false),fileName=ref(''),fps=ref(60),res=ref('--'),qualityPct=ref(100),bpm=ref('--'),railOpen=ref(false),inspOpen=ref(false),err=ref(null),q=ref(''),grpFilter=ref('');
  if(!VMAP[g.preset])g.preset='bars';
  let saveT=0,statusTimer=0,meterRaf=0,resizeObserver=null,audioUrl='';
  const onPlay=()=>playing.value=true,onPause=()=>playing.value=false;
  const save=()=>{clearTimeout(saveT);saveT=setTimeout(()=>saveState(g,params,dark.value),220);};
  const sync=()=>{Engine.S={...g,playing:playing.value};Engine.P={...(params[g.preset]||{})};};
  watch(g,()=>{sync();save();},{deep:true});watch(params,()=>{sync();save();},{deep:true});watch(playing,sync);
  const current=computed(()=>VMAP[g.preset]||VIS[0]),p=computed(()=>params[g.preset]||{}),paramKeys=computed(()=>Object.keys(current.value.params));
  const groupList=[{id:'waves',name:'Волны'},{id:'spectrum',name:'Спектр'},{id:'radial',name:'Формы'},{id:'particles',name:'Частицы'},{id:'futuristic',name:'Футуризм'},{id:'neon',name:'Неон · новое'},{id:'reference-new',name:'Референсы · новое'},{id:'spectrum-lab',name:'Spectrum Lab · новое'},{id:'beyond-spectrum',name:'Beyond Spectrum · новое'}];
  const groupShort={waves:'Волны',spectrum:'Спектр',radial:'Формы',particles:'Частицы',futuristic:'Футуризм',neon:'Неон · новое','reference-new':'Референсы · новое','spectrum-lab':'Spectrum Lab · новое','beyond-spectrum':'Beyond Spectrum · новое'};
  const filtered=computed(()=>{const s=q.value.trim().toLowerCase();return VIS.filter(v=>(!grpFilter.value||v.group===grpFilter.value)&&(!s||v.name.toLowerCase().includes(s)||v.id.toLowerCase().includes(s)));});
  const algoList=Object.keys(ALGOS).map(id=>({id,name:ALGOS[id].name})),algoHint=computed(()=>(ALGOS[g.algo]||ALGOS.balanced).hint),bandKeys=[{k:'gBass',label:'Bass',short:'Bass'},{k:'gLowMid',label:'Low-mid',short:'Low'},{k:'gMid',label:'Mid',short:'Mid'},{k:'gHighMid',label:'High-mid',short:'High'},{k:'gTreble',label:'Treble',short:'Trbl'}],globalKeys={react:['amp','speed','smooth','trail'],frame:['zoomW','zoomH','posX','posY']},formats=['16:9','9:16','1:1','4:5','4:3','21:9','2:1'];
  const frameStyle=computed(()=>{const[a,b]=g.format.split(':').map(Number);return{'--ar':a+'/'+b,'--arn':a/b};}),sourceLabel=computed(()=>mic.value?'Микрофон · live':fileName.value||(g.demo?'Демо-сигнал':'Источник не выбран')),fmt=v=>typeof v==='number'?(Number.isInteger(v)?v:v.toFixed(2).replace(/0$/,'')):v,setP=(k,v)=>{params[g.preset][k]=v;};
  const resetParams=()=>Object.keys(current.value.params).forEach(k=>params[g.preset][k]=current.value.params[k].def),randomParams=()=>Object.keys(current.value.params).forEach(k=>{const d=current.value.params[k];if(d.type==='toggle')params[g.preset][k]=Math.random()>.5;else if(d.type!=='select'){const raw=d.min+Math.random()*(d.max-d.min);params[g.preset][k]=Math.round(raw/d.step)*d.step;}}),cyclePreset=dir=>{const list=filtered.value.length?filtered.value:VIS,i=list.findIndex(v=>v.id===g.preset);g.preset=list[(i+dir+list.length)%list.length].id;},randomPreset=()=>{const list=filtered.value.length?filtered.value:VIS;g.preset=list[(Math.random()*list.length)|0].id;};
  const applyMusic=()=>{const m=MUSIC[g.music];if(!m)return;[g.gBass,g.gLowMid,g.gMid,g.gHighMid,g.gTreble]=m.bands;g.smooth=m.smooth;g.amp=m.amp;g.speed=m.speed;g.algo=m.algo;g.trail=m.trail;};
  const setPalette=pal=>{g.c1=pal.c1;g.c2=pal.c2;},resetFrame=()=>{g.zoomW=g.zoomH=1;g.posX=g.posY=50;};
  const toggleTheme=()=>{dark.value=!dark.value;document.documentElement.classList.toggle('dark',dark.value);save();};
  const loadFile=f=>{if(!f)return;if(f.type&&!f.type.startsWith('audio/')){err.value={id:'source',msg:'Выберите поддерживаемый аудиофайл'};return;}Audio.ensure(audioEl.value);revoke(audioUrl);audioUrl=URL.createObjectURL(f);audioEl.value.src=audioUrl;fileName.value=f.name;hasFile.value=true;g.demo=false;mic.value=false;Audio.micOff();audioEl.value.play().catch(()=>{err.value={id:'source',msg:'Браузер не смог воспроизвести этот формат'};});};
  const onFile=e=>{loadFile(e.target.files[0]);e.target.value='';},onDrop=e=>{drag.value=false;loadFile(e.dataTransfer.files[0]);};
  const togglePlay=async()=>{const el=audioEl.value;if(!el.src)return;Audio.ensure(el);await Audio.ac.resume();if(el.paused)await el.play().catch(()=>{});else el.pause();};
  const toggleMic=async()=>{Audio.ensure(audioEl.value);await Audio.ac.resume();if(mic.value){Audio.micOff();mic.value=false;return;}try{audioEl.value.pause();await Audio.micOn();mic.value=true;g.demo=false;err.value=null;}catch(error){err.value={id:'microphone',msg:error?.message||'Нет доступа к микрофону'};}};
  const snapshot=()=>{if(!Engine.canvas)return;Engine.canvas.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='eqlab-'+g.preset+'.png';a.click();setTimeout(()=>revoke(url),0);},'image/png');};
  const toggleFull=()=>document.fullscreenElement?document.exitFullscreen():frameEl.value?.requestFullscreen?.();
  onMounted(()=>{Engine.mount(canvasEl.value);Engine.onErr=(id,msg)=>{err.value={id,msg};};sync();Engine.resize();Engine.start();resizeObserver=new ResizeObserver(()=>Engine.resize());resizeObserver.observe(frameEl.value);const el=audioEl.value;el.addEventListener('play',onPlay);el.addEventListener('pause',onPause);statusTimer=setInterval(()=>{fps.value=Engine.fps;res.value=Engine.canvas?Engine.canvas.width+'×'+Engine.canvas.height:'--';qualityPct.value=Math.round(Engine.q*100);bpm.value=Audio.bpm||'--';},500);const bands=['bass','lowMid','mid','highMid','treble'];const paint=()=>{for(let i=0;i<5;i++)if(meterEls[i])meterEls[i].style.transform='scaleX('+clamp(Audio[bands[i]],0,1)+')';meterRaf=requestAnimationFrame(paint);};meterRaf=requestAnimationFrame(paint);watch(()=>g.format,()=>nextTick(()=>Engine.resize()));});
  onUnmounted(()=>{clearTimeout(saveT);clearInterval(statusTimer);cancelAnimationFrame(meterRaf);resizeObserver?.disconnect();const el=audioEl.value;el?.removeEventListener('play',onPlay);el?.removeEventListener('pause',onPause);Engine.stop();Engine.onErr=null;revoke(audioUrl);audioUrl='';disposeEffects();void disposeAudio(el);});
  return{g,params,p,current,paramKeys,dark,playing,mic,hasFile,drag,fps,res,qualityPct,bpm,railOpen,inspOpen,err,q,grpFilter,filtered,groupList,groupShort,algoList,algoHint,bandKeys,globalKeys,gschema:GSCHEMA,formats,palettes:PALETTES,frameStyle,sourceLabel,audioEl,canvasEl,frameEl,beatEl,meterEls,fmt,setP,resetParams,randomParams,cyclePreset,randomPreset,applyMusic,setPalette,resetFrame,toggleTheme,onFile,onDrop,togglePlay,toggleMic,snapshot,toggleFull};
}};
</script>
<template><div id="app" v-cloak class="shell"><header class="flex items-center gap-3 px-4 py-2.5 border-b" style="border-color:var(--line);background:var(--panel)"><button class="btn xl:hidden" @click="railOpen=!railOpen">☰</button><div class="flex items-baseline gap-2.5 min-w-0"><span class="mono font-bold text-[13px] tracking-[0.2em]">EQ&nbsp;LAB</span><span class="mono text-[10px] tracking-[0.14em] uppercase truncate" style="color:var(--ink-3)">{{sourceLabel}}</span></div><div class="ml-auto flex items-center gap-2"><span class="hidden sm:inline mono text-[10px] nums" style="color:var(--ink-3)">{{fps}} FPS / {{res}} / Q{{qualityPct}}</span><select v-model="g.format" style="width:auto;min-width:88px" class="mono text-[12px]"><option v-for="f in formats" :key="f">{{f}}</option></select><button class="btn" @click="snapshot">PNG</button><button class="btn" @click="toggleFull">⛶</button><button class="btn" @click="toggleTheme">{{dark?'☀':'☾'}}</button><button class="btn xl:hidden" @click="inspOpen=!inspOpen">⚙</button></div></header><div class="body-row"><aside class="rail" :class="{open:railOpen}"><details class="sec" open><summary>Источник</summary><div class="sec-body flex flex-col gap-2.5"><div class="grid grid-cols-2 gap-2"><label class="btn">Файл<input type="file" accept="audio/*" class="hidden" @change="onFile"></label><button class="btn" :class="{'btn-live':mic}" @click="toggleMic">{{mic?'Стоп мик':'Микрофон'}}</button></div><button class="btn btn-primary" @click="togglePlay" :disabled="!hasFile">{{playing?'⏸ Пауза':'▶ Играть'}}</button><audio ref="audioEl" controls preload="metadata"></audio><label class="flex items-center justify-between gap-3 text-[12.5px]" style="color:var(--ink-2)">Демо-сигнал без звука<span class="sw" :data-on="g.demo" role="switch" @click="g.demo=!g.demo"><i></i></span></label></div></details><details class="sec" open><summary>Визуализатор · {{filtered.length}}</summary><div class="sec-body flex flex-col gap-2.5"><input type="search" v-model="q" placeholder="Поиск: beyond, nebula, fluid…"><div class="flex flex-wrap gap-1.5"><button class="chip" v-for="grp in groupList" :key="grp.id" :aria-pressed="grpFilter===grp.id" @click="grpFilter=grpFilter===grp.id?'':grp.id">{{grp.name}}</button></div><div class="plist" role="listbox"><button v-for="v in filtered" :key="v.id" class="pitem" role="option" :aria-current="g.preset===v.id" @click="g.preset=v.id"><b></b><span>{{v.name}}</span><em>{{groupShort[v.group]}}</em></button><p v-if="!filtered.length" class="text-[12px] py-3 px-1" style="color:var(--ink-3)">Ничего не нашлось.</p></div><div class="grid grid-cols-2 gap-2"><button class="btn" @click="cyclePreset(-1)">← Пред</button><button class="btn" @click="cyclePreset(1)">След →</button></div><button class="btn" @click="randomPreset">🎲 Случайный</button></div></details><details class="sec" open><summary>Реакция на звук</summary><div class="sec-body flex flex-col gap-3"><label class="block"><span class="plabel">Алгоритм</span><select v-model="g.algo"><option v-for="a in algoList" :key="a.id" :value="a.id">{{a.name}}</option></select></label><p class="text-[11.5px]" style="color:var(--ink-3)">{{algoHint}}</p><label class="block"><span class="plabel">Жанровый пресет</span><select v-model="g.music" @change="applyMusic"><option value="custom">Custom</option><option value="edm">EDM / Bass</option><option value="ambient">Ambient</option><option value="rock">Rock</option><option value="hiphop">Hip-Hop</option><option value="classical">Classical</option><option value="podcast">Voice / Podcast</option></select></label><div v-for="k in globalKeys.react" :key="k"><span class="plabel">{{gschema[k].label}}<span class="pval">{{fmt(g[k])}}</span></span><input type="range" :min="gschema[k].min" :max="gschema[k].max" :step="gschema[k].step" :value="g[k]" @input="g[k]=+$event.target.value"></div></div></details><div class="legacy-frame-placeholder" aria-hidden="true"></div></aside><main class="stage" ref="stageEl"><div class="frame" ref="frameEl" :style="frameStyle" @dragover.prevent="drag=true" @dragleave="drag=false" @drop.prevent="onDrop"><canvas ref="canvasEl"></canvas><div class="drop" v-if="drag">Отпустите трек</div></div><div class="stage-foot flex items-center gap-4"><div class="flex-1 grid grid-cols-5 gap-2"><div v-for="(b,i) in bandKeys" :key="b.k"><div class="meter"><i :ref="el=>meterEls[i]=el"></i></div><span class="mono text-[9px]" style="color:var(--ink-3)">{{b.short}}</span></div></div><span class="mono text-[10px]" style="color:var(--ink-3)">BEAT · {{bpm}} BPM</span></div><p v-if="err" class="mono text-[11px]" style="color:var(--accent)">Визуализатор «{{err.id}}» упал: {{err.msg}}</p></main><aside class="insp" :class="{open:inspOpen}"><div class="px-4 pt-4 pb-3 border-b sticky top-0" style="border-color:var(--line);background:var(--panel)"><div class="mono text-[10px]" style="color:var(--ink-3)">Параметры</div><h2 class="text-[19px] font-semibold">{{current.name}}</h2><div class="mono text-[10px]" style="color:var(--ink-3)">{{groupShort[current.group]}} · {{paramKeys.length}} контролов</div><div class="grid grid-cols-2 gap-2 mt-3"><button class="btn" @click="resetParams">Сброс</button><button class="btn" @click="randomParams">🎲 Случайно</button></div></div><details class="sec" open><summary>Кадр EQ</summary><div class="sec-body flex flex-col gap-3"><div v-for="k in globalKeys.frame" :key="k"><span class="plabel">{{gschema[k].label}}<span class="pval">{{fmt(g[k])}}</span></span><input type="range" :min="gschema[k].min" :max="gschema[k].max" :step="gschema[k].step" :value="g[k]" @input="g[k]=+$event.target.value"></div><button class="btn" @click="resetFrame">Сбросить кадр EQ</button></div></details><details class="sec" open><summary>Цвет EQ</summary><div class="sec-body flex flex-col gap-3"><label><span class="plabel">Режим</span><select v-model="g.colorMode"><option value="duo">Дуо-градиент</option><option value="single">Один цвет</option><option value="spectrum">Спектр</option><option value="split">Сплит</option></select></label><div class="grid grid-cols-2 gap-2"><label><span class="plabel">A</span><input type="color" v-model="g.c1"></label><label><span class="plabel">B</span><input type="color" v-model="g.c2"></label></div><label><span class="plabel">Прокрутка оттенка</span><input type="range" min="0" max="2" step=".02" v-model.number="g.cycle"></label></div></details><div class="px-4 py-4 flex flex-col gap-3.5"><template v-for="k in paramKeys" :key="k"><label v-if="current.params[k].type==='toggle'" class="flex items-center justify-between gap-3 text-[12.5px]">{{current.params[k].label}}<span class="sw" :data-on="!!p[k]" role="switch" @click="setP(k,!p[k])"><i></i></span></label><label v-else-if="current.params[k].type==='select'"><span class="plabel">{{current.params[k].label}}</span><select :value="p[k]" @change="setP(k,$event.target.value)"><option v-for="option in current.params[k].options" :key="option" :value="option">{{option}}</option></select></label><div v-else><span class="plabel">{{current.params[k].label}}<span class="pval">{{fmt(p[k])}}</span></span><input type="range" :min="current.params[k].min" :max="current.params[k].max" :step="current.params[k].step" :value="p[k]" @input="setP(k,+$event.target.value)"></div></template></div></aside></div><div class="scrim xl:hidden" v-if="railOpen||inspOpen" @click="railOpen=false;inspOpen=false"></div></div></template>
